            ITEM(val, i, vec) /= ITEM(volumes, i, NULL);
        """, val = val,
            ids = numerix.array(numerix.MA.filled(ids, 0)),
            orientations = numerix.array(numerix.MA.filled(orientations, 0)),
            volumes = numerix.array(volumes),
